"""Freeze Phase-1 design and gold-only inputs. Never reads released test labels."""
import hashlib,json,subprocess,unicodedata,sys
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'docs/audits/icsai_phase1'
DATA=ROOT/'data/icsai_phase1/gold_clean'
RESTORE = '--restore-inputs' in sys.argv
if (OUT/'experiment_matrix.json').exists() and not RESTORE:
    raise SystemExit('Design already frozen; use --restore-inputs only to reconstruct identical input bytes. Amend design explicitly, never silently refreeze.')
expected = json.loads((OUT/'gold_input_manifest.json').read_text()) if RESTORE else None
DATA.mkdir(parents=True,exist_ok=True)
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def norm(s): return ' '.join(unicodedata.normalize('NFKC',s).casefold().split())
def read(p): return [json.loads(l) for l in p.read_text().splitlines() if l.strip()]
names=['eng_restaurant','eng_laptop','jpn_hotel','rus_restaurant','tat_restaurant','ukr_restaurant','zho_restaurant','zho_laptop']
manifest=[]
for name in names:
    lang=name.split('_')[0]; base=ROOT/'data/subtask_3'/lang
    train=base/f'{name}_train_alltasks.jsonl'; dev=base/f'{name}_dev_task3.jsonl'; test=base/f'{name}_test_task3.jsonl'
    source=read(train); dv={norm(r['Text']) for r in read(dev)}; ts={norm(r['Text']) for r in read(test)}
    kept=[]; removed=[]
    for i,r in enumerate(source):
        key=norm(r['Text']); reason=[s for s,ss in [('dev_text',dv),('unlabelled_test_text',ts)] if key in ss]
        if reason: removed.append({'source_row_1based':i+1,'id':r['ID'],'text_sha256':hashlib.sha256(key.encode()).hexdigest(),'reason':reason})
        else: kept.append(r)
    dest=DATA/f'{name}.jsonl'
    payload=''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in kept)
    if RESTORE:
        old=next(x for x in expected['datasets'] if x['dataset']==name)
        assert sha(train)==old['source_sha256'] and sha(dev)==old['dev_sha256'] and sha(test)==old['test_input_sha256'], 'Source changed; do not restore with a different split'
        assert hashlib.sha256(payload.encode()).hexdigest()==old['train_sha256'], 'Output differs from frozen input'
    dest.write_text(payload)
    manifest.append({'dataset':name,'source':str(train.relative_to(ROOT)),'source_sha256':sha(train),'source_rows':len(source),'train_file':str(dest.relative_to(ROOT)),'train_sha256':sha(dest),'kept_rows':len(kept),'removed':removed,'dev_file':str(dev.relative_to(ROOT)),'dev_sha256':sha(dev),'test_input':str(test.relative_to(ROOT)),'test_input_sha256':sha(test),'unique_kept_normalized_texts':len({norm(r['Text']) for r in kept}),'train_eval_exact_overlap_after':0,'category_inventory_train':sorted({q['Category'] for r in kept for q in r.get('Quadruplet',[])})})
if RESTORE:
    assert manifest == expected['datasets'], 'Input manifest differs'
    print('Restored eight byte-identical frozen gold inputs; design unchanged')
    raise SystemExit(0)
(OUT/'gold_input_manifest.json').write_text(json.dumps({'normalization':'NFKC+casefold+whitespace','policy':'Exclude train rows matching dev or unlabelled test texts; preserve remaining row order and within-train multiplicity. No test labels read; exact-match audit does not exclude semantic/paraphrase overlap.','datasets':manifest},ensure_ascii=False,indent=2)+'\n')
